INSERT INTO public.rubric_criteria (rubric_id, key, label, description, anchors, weight, position) VALUES
  ('17ad2f46-76ef-4138-9153-eb6867aa6e99', 'motivation', 'Motivation & fit with 180DC', 'Why 180DC, why now; specific, not generic', '{"1":"Generic or missing","3":"Clear but generic","5":"Specific, personal and convincing"}'::jsonb, 1.5, 0),
  ('17ad2f46-76ef-4138-9153-eb6867aa6e99', 'impact_orientation', 'Impact orientation', 'Evidence of caring about social or environmental impact', '{"1":"No evidence","3":"Some interest","5":"Track record of impact work"}'::jsonb, 1.2, 1),
  ('17ad2f46-76ef-4138-9153-eb6867aa6e99', 'analytical_thinking', 'Analytical thinking', 'Structured reasoning, use of evidence', '{"1":"Unstructured","3":"Mostly structured","5":"Sharp, structured, evidence-based"}'::jsonb, 1.2, 2),
  ('17ad2f46-76ef-4138-9153-eb6867aa6e99', 'communication', 'Written communication', 'Clarity, conciseness, tone', '{"1":"Hard to follow","3":"Clear","5":"Crisp and compelling"}'::jsonb, 1, 3),
  ('17ad2f46-76ef-4138-9153-eb6867aa6e99', 'teamwork', 'Teamwork & collaboration', 'Works well in diverse teams', '{"1":"No evidence","3":"Some examples","5":"Strong, reflected examples"}'::jsonb, 1, 4),
  ('0e37c7f4-ec60-44a0-8595-2b2efc86dae7', 'problem_solving', 'Case: problem solving', 'Hypothesis-driven structure, math, insight', '{"1":"Lost","3":"Solid","5":"Outstanding"}'::jsonb, 1.5, 0),
  ('0e37c7f4-ec60-44a0-8595-2b2efc86dae7', 'structured_communication', 'Structured communication', 'Top-down, synthesis, listening', '{"1":"Unclear","3":"Clear","5":"Partner-level"}'::jsonb, 1.2, 1),
  ('0e37c7f4-ec60-44a0-8595-2b2efc86dae7', 'client_orientation', 'Client orientation', 'Empathy for NGOs / social enterprises', '{"1":"None","3":"Some","5":"Strong"}'::jsonb, 1, 2),
  ('0e37c7f4-ec60-44a0-8595-2b2efc86dae7', 'team_fit', 'Team fit', 'Collaborative, coachable, humble', '{"1":"Concerns","3":"Good","5":"Excellent"}'::jsonb, 1, 3),
  ('0e37c7f4-ec60-44a0-8595-2b2efc86dae7', 'drive', 'Drive & ownership', 'Takes initiative, follows through', '{"1":"Low","3":"Good","5":"Exceptional"}'::jsonb, 1, 4);
